def materialize(log=print) -> Path:
    """把内嵌文件解包到 runtime 目录；内容一致则跳过。"""
    rt = runtime_dir()
    n_new = n_same = 0
    for rel, b64 in _EMBEDDED.items():
        target = rt / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        blob = base64.b64decode(b64)
        if target.exists():
            try:
                if target.read_bytes() == blob:
                    n_same += 1
                    continue
            except OSError:
                pass
        target.write_bytes(blob)
        n_new += 1
    log(f"[core] 内嵌文件就绪：{n_same} 个已存在，{n_new} 个新写入 → {rt}")
    return rt


# ---------------------------------------------------------------------------
# 通用工具
# ---------------------------------------------------------------------------

_ANSI = re.compile(r"\033\[[0-9;]*m")


def strip_ansi(s: str) -> str:
    return _ANSI.sub("", s)


# 运行日志着色：命中即返回 tk 文本标签名（None = 默认色）
_LOG_OK_MARKS = ("✓", "models OK", "chat OK")
_LOG_ERR_MARKS = ("失败", "✗", "ERROR", "错误", "Traceback")


def log_line_tag(line: str) -> str | None:
    """判断一行运行日志该用哪个颜色标签：失败→"err"，成功→"ok"，其余→None。

    只检查第一个 "·" 之前的“结论段”（形如
    `[mc] 测试 http://…/v1/chat/completions → chat OK(qwen3.8-flash)`），
    因为 "·" 之后是模型回答正文，正文里出现“失败/OK”等词不该影响这一行的颜色。
    """
    head = line.split("·", 1)[0]
    if any(m in head for m in _LOG_ERR_MARKS):
        return "err"
    if "HTTP 4" in head or "HTTP 5" in head:   # 上游 4xx/5xx 同样算失败
        return "err"
    if any(m in head for m in _LOG_OK_MARKS):
        return "ok"
    return None


def port_free(host: str, port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        try:
            s.bind((host, port))
            return True
        except OSError:
            return False


def _port_owner_pid(port: int) -> int | None:
    """查占用该端口 LISTEN 的进程 pid（Windows netstat），查不到返回 None。"""
    try:
        out = subprocess.run(["netstat", "-ano", "-p", "TCP"], capture_output=True,
                             timeout=15, text=True, errors="replace").stdout or ""
    except Exception:
        return None
    for line in out.splitlines():
        parts = line.split()
        if len(parts) == 5 and parts[0] == "TCP" and parts[3] == "LISTENING":
            try:
                if int(parts[1].rsplit(":", 1)[1]) == port:
                    return int(parts[4])
            except (ValueError, IndexError):
                continue
    return None


def _pid_command(pid: int) -> str:
    try:
        r = subprocess.run(["powershell", "-NoProfile", "-Command",
                            f"(Get-CimInstance Win32_Process -Filter 'ProcessId={pid}').CommandLine"],
                           capture_output=True, timeout=20, text=True, errors="replace")
        return r.stdout or ""
    except Exception:
        return ""


def probe_local_chat(base_url: str, model: str, timeout: int = 60) -> bool | None:
    """经本地反代低成本探测模型：True 存活 / False 已下线 / None 未知（服务未起/网络错）。
    system+hi 最小请求；只有明确的“模型不存在”类 400 才判死。"""
    import urllib.request
    body = json.dumps({"model": model, "messages": [
        {"role": "system", "content": "you are a helpful assistant"},
        {"role": "user", "content": "hi"}], "max_tokens": 5, "stream": False}).encode()
    req = urllib.request.Request(base_url.rstrip("/") + "/chat/completions", data=body,
                                 headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
        choices = (d or {}).get("choices") or []
        return True if choices else None
    except Exception as e:  # noqa: BLE001
        msg = ""
        try:
            import urllib.error
            if isinstance(e, urllib.error.HTTPError):
                msg = e.read().decode("utf-8", "replace")[:300]
        except Exception:
            pass
        low = msg.lower()
        if any(k in low for k in ("service info not found", "not exposed", "model not found",
                                  "unknown model", "invalid model", "not registered",
                                  "route missed", "unsupported",
                                  "不存在", "未注册", "不支持", "已下线", "无此模型")):
            return False
        return None


def _post_chat_json(base_url: str, payload: dict, timeout: int) -> tuple[int, str]:
    """POST 到本地反代的 /chat/completions；返回 (status, body_text)。

    传输层失败返回 (-1, 描述)；HTTPError 也把 body 读出来（诊断信息在里面）。
    """
    import urllib.request
    import urllib.error
    req = urllib.request.Request(base_url.rstrip("/") + "/chat/completions",
                                 data=json.dumps(payload).encode(),
                                 headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        try:
            return e.code, e.read().decode("utf-8", "replace")
        except Exception:  # noqa: BLE001
            return e.code, ""
    except Exception as e:  # noqa: BLE001
        return -1, f"{type(e).__name__}: {e}"


def _tool_choice_rejected(status: int, body: str) -> bool:
    """上游是否在抱怨 tool_choice 的格式（而不是别的错）。"""
    if status not in (400, 422):
        return False
    low = (body or "").lower()
    return "tool_choice" in low or "toolchoice" in low


def probe_model_tools(base_url: str, model: str, timeout: int = 90) -> bool | None:
    """经本地反代探测模型是否支持工具调用：True 支持 / False 不支持 / None 未知。

    判据是「强制调用工具」的请求能否返回 tool_calls。但**各通道上游对
    tool_choice 的接受程度不一样**：mc 的官方代理两种协议都接受对象形式，
    而 WorkBuddy(CodeBuddy) 上游是 Go 服务，其 tool_choice 字段类型是 string，
    收到 {"type":"function",...} 这种对象会直接 400
    （`cannot unmarshal object into Go struct field Request.tool_choice of type string`）。
    所以按精度**逐级降级**：

      1. 对象形式 {"type":"function","function":{"name":…}} —— 最精确
      2. 字符串 "required" —— 语义等价（必须调用工具，但不限定哪个），够探测用
      3. 字符串 "auto" —— 只能**证明支持**（真的回了 tool_calls），证不了不支持

    降级只在明确是 tool_choice 格式问题时发生，其它错误（鉴权/模型不存在）直接
    记 None，不浪费请求。
    """
    tool = [{"type": "function",
             "function": {"name": "cap_probe",
                          "description": "能力探测占位工具；被要求时必须调用它。",
                          "parameters": {"type": "object",
                                         "properties": {"ok": {"type": "boolean"}},
                                         "required": ["ok"]}}}]
    base_payload = {"model": model,
                    # 首条必须是 system：WorkBuddy(CodeBuddy) 上游强制要求，
                    # 否则回 400 code 11128「first message is not system prompt」。
                    "messages": [{"role": "system", "content": "you are a helpful assistant"},
                                 {"role": "user", "content": "调用 cap_probe，ok 传 true。"}],
                    "tools": tool, "max_tokens": 200, "stream": False}

    for choice, forced in (({"type": "function", "function": {"name": "cap_probe"}}, True),
                           ("required", True),
                           ("auto", False)):
        status, text = _post_chat_json(base_url, dict(base_payload, tool_choice=choice), timeout)
        if status == -1:                      # 传输层失败：未知
            return None
        if status == 200:
            try:
                d = json.loads(text)
            except Exception:  # noqa: BLE001
                return None
            choices = (d or {}).get("choices") or []
            if not choices:
                return None
            got = bool((choices[0].get("message") or {}).get("tool_calls"))
            if got:
                return True
            # 强制调用却没回 tool_calls → 判定不支持；
            # auto 下没回只能算未知（模型可以合法地选择不调工具）
            return False if forced else None
        if _tool_choice_rejected(status, text):
            continue                          # 换下一种形式重试
        return None                           # 其它错误：未知
    return None


def probe_model_speed(base_url: str, model: str, timeout: int = 90,
                      max_tokens: int = 64) -> dict:
    """快速测一次模型的「首字延迟」和「生成速度」。

    走流式请求，量三个值：
      · first   —— 首字延迟（发出请求 → 第一个 delta 到达），真实测量
      · tps     —— 生成速度（首字之后每秒产出多少 delta）
      · tokens  —— 产出量的口径

    注意速度是**估算**：本网关的流式响应不带 usage（OpenAI 要
    stream_options.include_usage 才有），所以拿不到精确的 completion_tokens，
    只能数 delta 个数当近似。因此返回值带 estimated=True，界面/日志要标明「约」。
    首字延迟不受此影响，是准的。
    """
    import urllib.request
    import urllib.error
    import time as _t
    payload = {"model": model,
               # 首条必须是 system：WorkBuddy(CodeBuddy) 上游强制要求，
               # 否则回 400 code 11128「first message is not system prompt」。
               # 对 mc 等通道也无害（system 会变成 instructions/system）。
               "messages": [{"role": "system", "content": "you are a helpful assistant"},
                            {"role": "user", "content": "用一句话说明什么是HTTP。"}],
               "max_tokens": max_tokens, "stream": True}
    req = urllib.request.Request(
        base_url.rstrip("/") + "/chat/completions",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json", "Accept": "text/event-stream"},
        method="POST")
    t0 = _t.time()
    first = None
    chunks = 0
    usage_tokens = None
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            if r.status != 200:
                return {"error": f"HTTP {r.status}"}
            for raw in r:                      # SSE 逐行读
                line = raw.decode("utf-8", "replace").strip()
                if not line.startswith("data:"):
                    continue
                p = line[5:].strip()
                if p == "[DONE]":
                    break
                try:
                    d = json.loads(p)
                except Exception:  # noqa: BLE001
                    continue
                ch = (d.get("choices") or [{}])[0]
                dl = ch.get("delta") or {}
                if dl.get("content") or dl.get("reasoning_content") or dl.get("tool_calls"):
                    chunks += 1
                    if first is None:
                        first = _t.time() - t0
                u = d.get("usage") or ch.get("usage") or {}
                if u.get("completion_tokens"):
                    usage_tokens = u["completion_tokens"]
    except Exception as e:  # noqa: BLE001
        return {"error": f"{type(e).__name__}: {e}"}
    elapsed = _t.time() - t0
    gen = (elapsed - first) if first is not None else None
    tokens = usage_tokens or chunks
    tps = (tokens / gen) if (gen and gen > 0 and tokens) else None
    return {"first": first, "tps": tps, "tokens": tokens, "elapsed": elapsed,
            "estimated": usage_tokens is None, "error": None}


def _fmt_speed(sp: dict) -> str:
    """把测速结果压成一行短文本（供日志）。"""
    if not sp or sp.get("error"):
        return f"测速失败（{sp.get('error') if sp else '无结果'}）"
    first = sp.get("first")
    tps = sp.get("tps")
    parts = []
    parts.append(f"首字 {first:.2f}s" if isinstance(first, (int, float)) else "首字 —")
    if isinstance(tps, (int, float)):
        parts.append(("约 " if sp.get("estimated") else "") + f"{tps:.1f} t/s")
    else:
        parts.append("速度 —")
    parts.append(f"{sp.get('tokens', 0)} 字")
    return " · ".join(parts)


# 模型刷新连续失败计数：同一通道连续失败 _MODEL_REFRESH_MAX_RETRIES 次后停止重试，
# 直到用户**再次点击该通道的「启动」按钮**（那时清零重来）。
# 只在点击启动时刷新，程序启动与定时循环都不再自动探测（用户要求：服务没起就别浪费资源）。
_MODEL_REFRESH_MAX_RETRIES = 3
_model_refresh_fail_count: dict = {}    # {通道: 连续失败次数}


def refresh_models_on_start(s: dict, log=print, local_bases: dict | None = None,
                           running: dict | None = None):
    """点击启动按钮时刷新各通道模型存活（daemon 线程调用，不阻塞）。

    只在**用户点击某个通道的「启动」按钮**时调用；不在程序启动、也不在定时循环里跑
    （用户要求：服务没起来就别浪费资源去探测）。

    cb 直连上游逐个探测；rc 取 catalog 即最新；mc/ca/lo/qd 仅在本地服务已起时经本地探测。
    结果写入 settings[{key}_verified]={ts, alive, checked, dead}，dialog 据此标注。

    连续失败 _MODEL_REFRESH_MAX_RETRIES 次后对该通道停止重试，直到下次点击启动按钮
    （重置计数器）—— 避免上游挂了还一直刷接口。
    """
    local_bases = local_bases or {}
    # running: {通道: 服务是否在跑}。**必须由调用方传入** —— 本函数在模块级，
    # 而 services 是 run_gui() 的局部变量，直接引用会 NameError（踩过）。
    _run = running or {}
    names = {"cb": "WorkBuddy", "mc": "MonkeyCode", "ca": "华为云",
             "rc": "小浣熊", "lo": "Loomy", "qd": "Qoder"}
    builtin = {"cb": list(CB_MODEL_CANDIDATES), "mc": list(MC_MODEL_CANDIDATES),
               "ca": list(CA_MODEL_CANDIDATES), "rc": list(RACOON_MODEL_CANDIDATES),
               "lo": list(LO_MODEL_CANDIDATES), "qd": list(QD_MODEL_CANDIDATES)}

    def _save(key: str, alive: list, checked: list, dead: list | None = None, extra: dict | None = None):
        prev = s.get(f"{key}_verified") or {}
        rec = {"ts": time.time(), "alive": alive, "checked": checked,
               "dead": dead if dead is not None else [m for m in checked if m not in alive]}
        if extra:
            rec.update(extra)
        else:  # 保留上次的工具探测结果，别被存活刷新抹掉
            for k in ("tools", "tools_ts"):
                if k in prev:
                    rec[k] = prev[k]
        s[f"{key}_verified"] = rec
        try:
            save_settings(s)
        except Exception:
            pass

    def _give_up(key: str) -> bool:
        """该通道是否已连续失败到上限（是则本次直接跳过，不再打上游）。"""
        n = _model_refresh_fail_count.get(key, 0)
        if n >= _MODEL_REFRESH_MAX_RETRIES:
            log(f"[models] {names[key]} 已连续失败 {n} 次，本次跳过"
                f"（下次点击「启动」时重置重试）")
            return True
        return False

    def _fail(key: str, err) -> None:
        n = _model_refresh_fail_count.get(key, 0) + 1
        _model_refresh_fail_count[key] = n
        tail = "" if n < _MODEL_REFRESH_MAX_RETRIES else f" —— 已 {n} 次，停止重试直到下次启动"
        log(f"[models] {names[key]} 刷新失败（{n}/{_MODEL_REFRESH_MAX_RETRIES}）："
            f"{type(err).__name__}: {err}{tail}")

    def _ok(key: str) -> None:
        _model_refresh_fail_count.pop(key, None)     # 成功即清零

    # cb：直连上游探测（不依赖本地服务）
    if _run.get("cb"):
        if _give_up("cb"):
            pass
        else:
            try:
                conv = import_converter()
                resolve = getattr(conv, "resolve_model", lambda m: m)
                cands = list(dict.fromkeys(list(builtin["cb"]) + [(resolve(m) or m) for m in (s.get("cb_models") or [])]))
                res = conv.probe_models(cands) if hasattr(conv, "probe_models") else {}
                alive = [k for k, v in res.items() if v is True]
                dead = [k for k, v in res.items() if v is False]
                _save("cb", alive, list(res.keys()), dead)
                _ok("cb")
                log(f"[models] WorkBuddy 刷新：{len(alive)}/{len(res)} 存活"
                    + (f" · 已下线：{', '.join(dead)}" if dead else ""))
            except Exception as e:  # noqa: BLE001
                _fail("cb", e)

    # rc：catalog 即最新（1 次请求，无逐个探测成本）
    if not _run.get("rc"):
        log("[models] 小浣熊刷新跳过（服务未启动）")
    elif _give_up("rc"):
        pass
    else:
        try:
            rc = import_raccoon()
            mp = rc.catalog_name_map() if hasattr(rc, "catalog_name_map") else {}
            if mp:
                _save("rc", list(mp.values()), list(mp.values()))
                _ok("rc")
                log(f"[models] 小浣熊刷新：catalog {len(mp)} 个（显示名优先）")
            else:
                log("[models] 小浣熊刷新：catalog 为空")
        except Exception as e:  # noqa: BLE001
            _fail("rc", e)

    # mc/ca/lo/qd：仅服务已起时经本地探测
    for key in ("mc", "ca", "lo", "qd"):
        if _give_up(key):
            continue
        base = local_bases.get(key)
        if not base or not _run.get(key):
            log(f"[models] {names[key]}刷新跳过（服务未启动）")
            continue
        try:
            # 凭据明显不可用时跳过：否则每个模型打一次请求，只会换来一串 503
            # （典型：CodeArts 会话过期 → 4 个模型 4 条 503 刷进日志），毫无意义。
            if key == "ca":
                _cam = sys.modules.get("codearts2openai")
                if _cam is not None and hasattr(_cam, "needs_login"):
                    try:
                        if _cam.needs_login():
                            log(f"[models] {names[key]}刷新跳过（凭据不可用，避免刷出大量 503）")
                            continue
                    except Exception:  # noqa: BLE001
                        pass
            cands = list(dict.fromkeys(list(builtin[key]) + list(s.get(f"{key}_models") or [])))
            res = {m: probe_local_chat(base, m) for m in cands}
            alive = [k for k, v in res.items() if v is True]
            dead = [k for k, v in res.items() if v is False]
            # 工具调用能力不在这里探测：每个模型一次请求、很慢（实测每个 5–10s）。
            # 改由模型对话框的「探测工具能力」按钮按需触发，只测勾选的模型。
            _save(key, alive, list(res.keys()), dead, None)
            _ok(key)
            log(f"[models] {names[key]} 刷新：{len(alive)}/{len(res)} 存活"
                + (f" · 已下线：{', '.join(dead)}" if dead else ""))
        except Exception as e:  # noqa: BLE001
            _fail(key, e)


def reclaim_stale_port(host: str, port: int, log=print) -> bool:
    """端口被占用时：若占用者是上回没退干净的 BuddyZGateway（含 --serve / GUI / 打包 exe），
    taskkill 关闭后返回 True；若是别的程序或查不到，返回 False（调用方保持报错）。"""
    pid = _port_owner_pid(port)
    if not pid:
        log(f"[port] 端口 {port} 被占用，但查不到占用进程")
        return False
    if pid == os.getpid():
        return False
    cmd = _pid_command(pid)
    if "buddyzgateway" not in cmd.lower():
        log(f"[port] 端口 {port} 被其他程序占用 (pid={pid})，不处理")
        return False
    log(f"[port] 端口 {port} 被残留的 BuddyZGateway 占用 (pid={pid})，正在关闭…")
    try:
        subprocess.run(["taskkill", "/F", "/PID", str(pid)], capture_output=True, timeout=15)
    except Exception as e:  # noqa: BLE001
        log(f"[port] 关闭残留进程失败：{e}")
        return False
    for _ in range(30):
        if port_free(host, port):
            break
        time.sleep(0.2)
    if port_free(host, port):
        log(f"[port] 残留进程已关闭，端口 {port} 已释放，继续启动")
        return True
    log(f"[port] 残留进程已关但端口 {port} 仍被占用")
    return False


def ts() -> str:
    return time.strftime("%H:%M:%S")


class Tee:
    """把 stdout/stderr 同时写到控制台和日志队列（供 GUI 显示）。"""

    def __init__(self):
        self.sink = None          # callable(str)
        self._orig_out = None
        self._orig_err = None

    def install(self, sink):
        self.sink = sink
        self._orig_out = sys.stdout
        self._orig_err = sys.stderr
        sys.stdout = self
        sys.stderr = self

    def write(self, s):
        for h in (self._orig_out, self._orig_err):
            if h is not None:
                try:
                    h.write(s)
                except Exception:
                    pass
        if self.sink:
            try:
                self.sink(s)
            except Exception:
                pass
        return len(s)

    def flush(self):
        for h in (self._orig_out, self._orig_err):
            if h is not None:
                try:
                    h.flush()
                except Exception:
                    pass

    def isatty(self):
        return False

    def reconfigure(self, **_kw):  # 某些依赖会对 stdout 调用它
        pass

    def fileno(self):
        return 1


# ---------------------------------------------------------------------------
# Python 依赖
# ---------------------------------------------------------------------------

REQUIRED_DEPS = [
    ("fastapi", "fastapi"),
    ("uvicorn[standard]", "uvicorn"),
    ("httpx", "httpx"),
    ("python-dotenv", "dotenv"),
    ("pystray", "pystray"),
    ("Pillow", "PIL"),
    # codearts2openai 需要的 DPoP 依赖
    ("PyJWT", "jwt"),
    ("cryptography", "cryptography"),
    ("pywin32", "win32crypt"),
    ("requests", "requests"),
]


def missing_deps() -> list[str]:
    if is_frozen():
        return []  # 依赖已随 exe 打包
    out = []
    for pip_name, mod in REQUIRED_DEPS:
        try:
            if importlib.util.find_spec(mod) is None:
                out.append(pip_name)
        except (ImportError, ValueError):
            out.append(pip_name)
    return out


def _invalidate_import_caches() -> None:
    """pip 装完后让本进程能立刻 import 新模块（find_spec 会吃旧负缓存）。"""
    importlib.invalidate_caches()
    try:
        import site
        for p in (site.getusersitepackages(), *site.getsitepackages()):
            if p:
                site.addsitedir(p)  # 处理 .pth（pywin32.pth 把 win32/ 加进 path）
    except Exception:
        pass


def install_deps(log=print) -> bool:
    """pip 安装缺失依赖；Program Files 下无权限时自动回退 --user。"""
    miss = missing_deps()
    if not miss:
        return True
    log(f"[deps] 正在安装缺失依赖：{' '.join(miss)} …")
    base = [sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check"] + miss
    for extra in ([], ["--user"]):
        cmd = base + extra
        try:
            p = subprocess.run(cmd, capture_output=True, text=True,
                               encoding="utf-8", errors="replace",
                               creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            if p.returncode == 0:
                _invalidate_import_caches()
                still = missing_deps()
                if still:
                    log(f"[deps] 已安装但本进程仍检测不到：{' '.join(still)}（重启网关即可生效）")
                    return False
                log("[deps] 依赖安装完成")
                return True
            log(f"[deps] pip 输出：{(p.stdout or '')[-500:]} {(p.stderr or '')[-800:]}")
        except Exception as e:  # noqa: BLE001
            log(f"[deps] pip 异常：{e}")
    pkgs = " ".join(p for p, _ in REQUIRED_DEPS)
    log(f"[deps] 依赖安装失败，请手动执行：\"{sys.executable}\" -m pip install {pkgs}")
    return False


# ---------------------------------------------------------------------------
# CodeBuddy 凭据检测（轻量，不依赖第三方库）
# ---------------------------------------------------------------------------

def find_cb_auth_file(station: str | None = None) -> Path | None:
    """找 WorkBuddy auth 文件。

    station: "cn" | "intl" | None
      - "cn"     → workbuddy-desktop.info      (国内 www.workbuddy.cn)
      - "intl"   → workbuddy-desktop-ai.info  (国际 www.workbuddy.ai)
      - None     → 兼容旧调用：优先找国际版，找不到再退回国内版
    """
    local = Path(os.environ.get("LOCALAPPDATA") or (Path.home() / "AppData" / "Local"))
    d = local / "CodeBuddyExtension" / "Data" / "Public" / "auth"
    if not d.is_dir():
        return None
    if station == "cn":
        p = d / "workbuddy-desktop.info"
        return p if p.is_file() else None
    if station == "intl":
        p = d / "workbuddy-desktop-ai.info"
        return p if p.is_file() else None
    # station is None: 兼容旧调用（不指定站点时，优先找国际版再退回国内版）
    # 这样既不破坏现有调用，又能让显式指定站点的调用精确生效
    for fname in ("workbuddy-desktop-ai.info", "workbuddy-desktop.info"):
        p = d / fname
        if p.is_file():
            return p
    return None


def read_cb_summary(station: str | None = None) -> dict:
    af = find_cb_auth_file(station)
    if af is None:
        return {"found": False, "station": station}
    try:
        data = json.loads(af.read_text(encoding="utf-8"))
        auth = data.get("auth") or {}
        acct = data.get("account") or {}
        exp = auth.get("expiresAt") or 0
        dom = auth.get("domain") or ""
        # 由 domain 反推实际站点，供 GUI 显示与后端选择（.ai → 国际，其余 → 国内）
        real_station = ("intl" if any(k in dom for k in ("workbuddy.ai", "codebuddy.ai"))
                        else "cn")
        return {
            "found": True,
            "path": str(af),
            "nickname": acct.get("nickname") or "?",
            "enterprise": acct.get("enterpriseName") or "-",
            "domain": dom or "-",
            "station": real_station,
            "expired": time.time() * 1000 >= (exp - 60_000),
            "expires_at": exp,
        }
    except Exception as e:  # noqa: BLE001
        return {"found": True, "path": str(af), "station": station, "error": str(e)}


# ---------------------------------------------------------------------------
# Windows DPI 感知（必须在创建 Tk 窗口之前调用，否则高分屏下文字偏小）
# ---------------------------------------------------------------------------

def enable_windows_dpi_awareness() -> bool:
    if sys.platform != "win32":
        return False
    try:
        import ctypes
        try:
            # Per-Monitor DPI Aware v2 (Win10 1703+)
            ctypes.windll.shcore.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4))
            return True
        except Exception:
            pass
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(2)  # Per-Monitor DPI Aware
            return True
        except Exception:
            pass
        try:
            ctypes.windll.user32.SetProcessDPIAware()  # System DPI Aware (fallback)
            return True
        except Exception:
            pass
    except Exception:
        pass
    return False


def _winstate_path() -> Path:
    """窗口状态文件（尺寸/位置/折叠状态）。"""
    return data_dir() / "ui_window.json"


def save_window_state(root, collapsed: dict, gezura: bool = False) -> None:
    """记下窗口几何与折叠状态，下次启动时原样恢复。

    gezura（最大化）单独记：最大化时 winfo_x/y 是"还原前"的坐标，
    直接存会让下次恢复到一个奇怪的位置。
    """
    try:
        wm = root.wm_state() if hasattr(root, "wm_state") else "normal"
        st = {
            "x": root.winfo_x(), "y": root.winfo_y(),
            "w": root.winfo_width(), "h": root.winfo_height(),
            "zoomed": bool(gezura or wm == "zoomed"),
            "collapsed": {str(k): bool(v) for k, v in (collapsed or {}).items()},
        }
    except Exception:          # noqa: BLE001  窗口可能已销毁
        return
    try:
        p = _winstate_path()
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(st, ensure_ascii=False, indent=2), encoding="utf-8")
    except OSError:
        pass                   # 存不了就算了，不该因此阻止退出


def load_window_state() -> dict:
    """读上次的窗口状态；没有/损坏则返回空 dict。"""
    try:
        d = json.loads(_winstate_path().read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else {}
    except Exception:          # noqa: BLE001
        return {}


def clamp_window_to_screen(root: "tk.Tk") -> None:
    """把窗口强制移回所在显示器的工作区（扣掉任务栏，多显示器安全）"""
    try:
        import ctypes
        root.update_idletasks()
        # 取窗口所在显示器的工作区 rcWork（已扣除任务栏）
        wa = None
        try:
            user32 = ctypes.windll.user32
            hwnd = root.winfo_id()

            class RECT(ctypes.Structure):
                _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                            ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

            class MONITORINFO(ctypes.Structure):
                _fields_ = [("cbSize", ctypes.c_ulong), ("rcMonitor", RECT),
                            ("rcWork", RECT), ("dwFlags", ctypes.c_ulong)]

            mon = user32.MonitorFromWindow(hwnd, 2)  # MONITOR_DEFAULTTONEAREST
            mi = MONITORINFO()
            mi.cbSize = ctypes.sizeof(MONITORINFO)
            if user32.GetMonitorInfoW(mon, ctypes.byref(mi)):
                wa = (mi.rcWork.left, mi.rcWork.top, mi.rcWork.right, mi.rcWork.bottom)
        except Exception:
            wa = None
        if wa is None:
            # 兜底：主屏全尺寸（至少不跑出屏幕外）
            wa = (0, 0, root.winfo_screenwidth(), root.winfo_screenheight())
        wl, wt, wr, wb = wa
        w = root.winfo_width()
        h = root.winfo_height()
        x = root.winfo_x()
        y = root.winfo_y()
        if x + w > wr:
            x = wr - w
        if y + h > wb:
            y = wb - h
        if x < wl:
            x = wl
        if y < wt:
            y = wt
        # 窗口比工作区还大时，至少保证左上角可见
        x = max(wl, min(x, wr - 50))
        y = max(wt, min(y, wb - 50))
        if (x, y) != (root.winfo_x(), root.winfo_y()):
            root.geometry(f"+{x}+{y}")
    except Exception:
        pass


# ---------------------------------------------------------------------------
# 本机软件安装位置检测
# ---------------------------------------------------------------------------
# 每个通道一张「探测画像」列表，按优先级排列：前面的先命中就返回。
# ca 有两个来源——华为云 CodeArts 桌面端优先（装了它就显示它），没装桌面端时
# 退回 VS Code：装了插件 huaweicloud.vscode-codebot 并登录，本通道一样可用
# （凭证解密走的是和桌面端同一套 v10 方案）。
_INSTALL_PROFILES: dict[str, list] = {
    # WorkBuddy 国内/国际是**两个独立安装**（版本号相同，exe 名不同）：
    #   国内 C:\Program Files\WorkBuddy\WorkBuddy.exe
    #   国际 C:\Program Files\WorkBuddyAI\WorkBuddyAI.exe
    # 目录名都含 "workbuddy"，所以这里要同时列两个 exe 名。
    "wb": [(("workbuddy", "codebuddy"), ("WorkBuddy.exe", "WorkBuddyAI.exe"))],
    "mc": [(("monkeycode",), ("monkeycode-desktop.exe",))],
    "rc": [(("raccoon", "xiaohuanxiong", "小浣熊"), ("商汤小浣熊.exe", "raccoon-ai.exe"))],
    "lo": [(("loomy",), ("Loomy.exe",))],
    # Qoder 国内/国际也是**两个独立安装**，靠 exe 名区分（目录名都含 qoder）：
    #   国际 %LOCALAPPDATA%\Programs\Qoder\Qoder.exe
    #   国内 C:\Program Files\Qoder CN\Qoder CN.exe
    "qd": [(("qoder",), ("Qoder.exe", "Qoder CN.exe"))],
    "ca": [
        # ① 华为云 CodeArts Agent 桌面端（优先）
        (("codearts",), ("codearts-agent.exe",)),
        # ② VS Code 系（装的是插件；目录名与凭证侧的 _VSCODE_USERDATA_DIRS 对应）
        (("microsoft vs code", "vscode", "vscodium"),
         ("Code.exe", "Code - Insiders.exe", "VSCodium.exe")),
    ],
}

# WorkBuddy 两版靠 **exe 名**区分（目录名无法区分）
WB_STATION_EXES = {
    "cn": ("WorkBuddy.exe",),        # 国内：C:\Program Files\WorkBuddy
    "intl": ("WorkBuddyAI.exe",),    # 国际：C:\Program Files\WorkBuddyAI
}
WB_STATION_LABEL = {"cn": "国内", "intl": "国际"}
# Qoder 同理：两个独立安装，目录名都含 "qoder"，只能靠 exe 名区分
QD_STATION_EXES = {
    "intl": ("Qoder.exe",),          # 国际：%LOCALAPPDATA%\Programs\Qoder
    "cn": ("Qoder CN.exe",),         # 国内：C:\Program Files\Qoder CN
}
# 两版各自的 auth 文件（同目录、不同文件名，因此可以同时登录互不覆盖）
WB_AUTH_FILES = {"cn": "workbuddy-desktop.info",       # 国内 www.workbuddy.cn
                 "intl": "workbuddy-desktop-ai.info"}  # 国际 www.workbuddy.ai


def _kind_profiles(kind: str) -> list:
    return _INSTALL_PROFILES.get(kind) or _INSTALL_PROFILES["ca"]


def _kind_exe_names(kind: str) -> tuple:
    """该通道所有来源的主程序名（按优先级去重）。"""
    out: list[str] = []
    for _hints, exes in _kind_profiles(kind):
        for e in exes:
            if e not in out:
                out.append(e)
    return tuple(out)


def resolve_install_input(path: str, kind: str) -> str:
    """用户选择的 exe 或文件夹 → 归一化：文件夹则自动定位其中的主程序 exe。

    ca 同时认 codearts-agent.exe（桌面端）和 Code.exe（VS Code），
    所以直接把 VS Code 的安装文件夹粘进来也能定位到 Code.exe。
    """
    p = (path or "").strip().strip('"')
    if not p:
        return ""
    if p.lower().endswith(".exe"):
        return p
    if Path(p).is_dir():
        for en in _kind_exe_names(kind):
            c = Path(p) / en
            if c.is_file():
                return str(c)
        try:
            for x in sorted(Path(p).glob("*.exe")):
                return str(x)
        except OSError:
            pass
    return p


def _scan_dirs_for(bases: list, hints: tuple, exe_names: tuple, dirs_cand: list) -> str:
    for b in bases:
        if not b:
            continue
        try:
            for name in os.listdir(b):
                low = str(name).lower()
                if any(h in low for h in hints):
                    d = os.path.join(b, name)
                    if os.path.isdir(d):
                        for en in exe_names:
                            p = os.path.join(d, en)
                            if os.path.isfile(p):
                                return p
                        dirs_cand.append(d)
        except OSError:
            continue
    return ""


def _scan_registry_for(hints: tuple, exe_names: tuple, dirs_cand: list) -> str:
    try:
        import winreg
    except ImportError:
        return ""
    roots = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_CURRENT_USER, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
    ]
    for hive, sub in roots:
        try:
            root_key = winreg.OpenKey(hive, sub)
        except OSError:
            continue
        with root_key:
            i = 0
            while True:
                try:
                    key_name = winreg.EnumKey(root_key, i)
                except OSError:
                    break
                i += 1
                try:
                    with winreg.OpenKey(root_key, key_name) as sk:
                        try:
                            disp, _ = winreg.QueryValueEx(sk, "DisplayName")
                        except OSError:
                            continue
                        if not any(h in str(disp).lower() for h in hints):
                            continue
                        for attr in ("DisplayIcon", "InstallLocation"):
                            try:
                                val, _ = winreg.QueryValueEx(sk, attr)
                            except OSError:
                                continue
                            val = str(val).split(",")[0].strip().strip('"')
                            if not val:
                                continue
                            if val.lower().endswith(".exe"):
                                if os.path.isfile(val):
                                    return val
                                val = os.path.dirname(val)
                            if val and os.path.isdir(val):
                                for en in exe_names:
                                    p = os.path.join(val, en)
                                    if os.path.isfile(p):
                                        return p
                                dirs_cand.append(val)
                except OSError:
                    continue
    return ""


def find_install(kind: str, station: str | None = None) -> str:
    """自动搜索本机安装位置：Program Files 系列 + 注册表卸载项。

    kind: 'wb' | 'mc' | 'ca' | 'rc' | 'lo'。按画像优先级返回第一个命中：
    ca 先找华为云 CodeArts 桌面端，桌面端不在才退回 VS Code。

    station: 只有 'wb' 用得上 —— "cn" 只找 WorkBuddy.exe（国内），
    "intl" 只找 WorkBuddyAI.exe（国际）。两版安装目录名都含 "workbuddy"，
    不指定站点时无法区分，只能靠 exe 名。
    """
    bases = [
        os.environ.get("ProgramFiles", r"C:\Program Files"),
        os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"),
        os.environ.get("ProgramW6432", r"C:\Program Files"),
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs"),
        os.environ.get("LOCALAPPDATA", ""),
    ]
    profiles = _kind_profiles(kind)
    if kind == "wb" and station in WB_STATION_EXES:
        profiles = [(("workbuddy", "codebuddy"), WB_STATION_EXES[station])]
    elif kind == "qd" and station in QD_STATION_EXES:
        profiles = [(("qoder",), QD_STATION_EXES[station])]
    dirs_cand: list[str] = []
    for hints, exe_names in profiles:
        hit = _scan_dirs_for(bases, hints, exe_names, dirs_cand)
        if hit:
            return hit
        hit = _scan_registry_for(hints, exe_names, dirs_cand)
        if hit:
            return hit
    return dirs_cand[0] if dirs_cand else ""


# ---------------------------------------------------------------------------
# 点「启动」缺凭据时：自动打开桌面端 → 等到凭据落地 → 自动关掉桌面端
# ---------------------------------------------------------------------------
# 用户诉求：「点某通道的启动按钮后，如果判断该通道需要重新登录桌面端，
# 则自动打开桌面端，拿到响应凭证后，再自动关闭该桌面端。」
#
# 设计要点（都是踩过的坑）：
#  ① **绝不阻塞 Tk 线程** —— 启动函数在 Tk 主线程里跑，等待最长 3 分钟。
#     所以这里只提供阻塞式的 auto_login_desktop()，由调用方丢进后台线程。
#  ② **只关自己拉起来的进程**：先快照同名进程 PID，登录完只杀新增的那些；
#     用户本来就开着的桌面端不动。（Electron 会派生一堆子进程，必须 /T。）
#  ③ install_kind 用的是 find_install() 认的 key —— WorkBuddy 是 "wb" 不是 "cb"。
_DESKTOP_LOGIN_SPEC: dict[str, dict] = {
    "cb": {"label": "WorkBuddy", "install_kind": "wb", "station": True,
           "hint": "国内 WorkBuddy.exe / 国际 WorkBuddyAI.exe"},
    "mc": {"label": "MonkeyCode", "install_kind": "mc", "station": False,
           "hint": "MonkeyCode 桌面端（安装后登录一次即可）"},
    "ca": {"label": "华为云 CodeArts", "install_kind": "ca", "station": False,
           "hint": "CodeArts Agent 桌面端，或 VS Code + CodeBuddy 插件",
           # VS Code 不是"登录桌面端"的流程，自动拉起它只会白开一个编辑器窗口
           "no_launch": ("Code.exe", "Code - Insiders.exe", "VSCodium.exe")},
    "qd": {"label": "Qoder", "install_kind": "qd", "station": True,
           "hint": "国际 Qoder.exe / 国内 Qoder CN.exe"},
    # rc / lo 不需要桌面端登录（凭据分别是浏览器 cookie 目录 / opencode 配置），
    # 因此不给它们做自动拉起 —— 写了也只是白开一个窗口。
}

DESKTOP_LOGIN_POLL = 3.0          # 轮询间隔（秒）
DESKTOP_LOGIN_TIMEOUT = 180.0     # 最长等待（秒），对齐 CodeArts 官方换票轮询量级
# 正在等待登录的通道 → 防止连点「启动」拉出一排桌面端窗口
_desktop_login_busy: set = set()
# CodeArts：拉起桌面端**之前**的凭证库 mtime。用户登录会重写 state.vscdb，
# 靠这个前后对比才能发现"刚刚登录完成"（否则永远等不到、白等到超时）。
_CA_STORE_BASELINE: dict = {}
_desktop_login_lock = threading.Lock()


def _pids_by_image(image: str) -> set:
    """当前所有名为 image 的进程 PID（Windows tasklist；失败返回空集）。"""
    if os.name != "nt":
        return set()
    try:
        # errors="replace"：tasklist 的输出是**本地编码**（中文 Windows 是 GBK），
        # 而本机 Python 跑在 UTF-8 模式下，严格解码会让读取线程直接抛
        # UnicodeDecodeError（读不到任何输出）。这里只要镜像名与 PID（都是 ASCII），
        # 所以容错解码就够了。
        r = subprocess.run(["tasklist", "/FI", f"IMAGENAME eq {image}",
                            "/FO", "CSV", "/NH"],
                           capture_output=True, text=True, errors="replace",
                           timeout=20)
    except Exception:  # noqa: BLE001
        return set()
    out = set()
    for line in (r.stdout or "").splitlines():
        parts = [x.strip().strip('"') for x in line.split('","')]
        if len(parts) >= 2 and parts[0].lower() == image.lower():
            try:
                out.add(int(parts[1]))
            except ValueError:
                pass
    return out


def _kill_pids(pids: set, label: str, log=print) -> None:
    """强制结束给定的进程树（/T 连子进程一起）。"""
    if not pids:
        return
    for pid in sorted(pids):
        try:
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                           capture_output=True, text=True, errors="replace",
                           timeout=20)
        except Exception:  # noqa: BLE001
            pass
    log(f"[登录] 已自动关闭 {label} 桌面端（pid={', '.join(str(p) for p in sorted(pids))}）")


def desktop_cred_probe(key: str, station: str | None = None) -> tuple:
    """该通道当前有没有可用的**桌面端登录态**。返回 (是否可用, 人话说明)。

    只读本地文件/内存，**不发网络请求**（这个函数会在等待循环里被反复调用）。
    """
    try:
        if key == "cb":
            conv = import_converter(lambda *a: None)
            if station:
                conv.CONFIG["station"] = station      # 让 find_auth_file 只看该版本
            af = conv.find_auth_file()
            if not af:
                return False, "未找到 WorkBuddy 登录文件"
            st = who = ""
            try:
                sm = conv.CredentialManager(af).summary()
                st = {"cn": "国内", "intl": "国际"}.get(sm.get("station"), "")
                who = sm.get("nickname") or sm.get("domain") or ""
            except Exception:  # noqa: BLE001
                pass
            return True, " ".join(x for x in (st, who) if x) or os.path.basename(af)
        if key == "mc":
            mc = import_monkeycode(lambda *a: None)
            if mc.needs_login():
                return False, "未找到 MonkeyCode 登录数据"
            d = mc.find_ohmyagent_key()
            if d:
                sv = str(d.get("server") or "")
                st = "国际" if ".net" in sv else ("国内" if ".com" in sv else "已登录")
                return True, st
            try:
                b, k = mc._load_from_desktop()
            except Exception:  # noqa: BLE001
                b = k = None
            if b and k:
                return True, "桌面端 config.json"
            return False, "未找到 MonkeyCode 登录数据"
        if key == "ca":
            ca = import_codearts(lambda *a: None)
            # ① 刚在桌面端/VS Code 登录完 → 凭证库被重写，且能解出会话。
            #    必须在 cred_status 之前判：那时内存与自家 state 都还是旧的。
            try:
                # ⚠ 只有在**我们正拉起桌面端等登录**时才走这条捷径（_base 已设）。
                # 否则凭证库里那条**早已过期的**登录记录会一直骗过探测，
                # 导致该自动登录的时候永远不触发（会退化成一堆 503）。
                _base = _CA_STORE_BASELINE.get("fp")
                if _base is not None:
                    _fp = ca.store_fingerprint()
                    if _fp > _base and ca.has_store_session():
                        return True, "刚完成桌面端登录（凭证库已更新）"
            except Exception:  # noqa: BLE001
                pass
            # ② 优先用 cred_status（零网络、真实可用性）
            st = ca.cred_status()
            if st.get("live"):
                left = st.get("expires_in")
                tail = f"（剩 {int(left // 60)} 分钟）" if isinstance(left, (int, float)) and left > 0 else ""
                return True, f"会话可用{tail}"
            # 没 live 但有 session/ticket 且 needs_login=False（内存里可能还可用）也算有
            if (st.get("has_session") or st.get("has_ticket")) and not ca.needs_login():
                left = st.get("expires_in")
                tail = f"（剩 {int(left // 60)} 分钟）" if isinstance(left, (int, float)) and left > 0 else ""
                return True, f"会话可用{tail}"
            return False, "CodeArts 尚无可用会话"
        if key == "qd":
            qd = import_qoder(lambda *a: None)
            _st = station or qd.CONFIG.get("station") or "intl"
            c = qd.credential_status(_st)
            if c.get("ide_found"):
                who = c.get("email") or c.get("phone") or c.get("account") or "桌面端登录态"
                return True, str(who)
            return False, "未找到 Qoder 桌面端登录态"
    except Exception as e:  # noqa: BLE001
        return False, f"{type(e).__name__}: {e}"
    return True, ""      # 其它通道（rc/lo）不需要桌面端登录


def auto_login_desktop(key: str, station: str | None = None, log=print) -> bool:
    """打开桌面端 → 等登录凭据落地 → 自动关闭桌面端。返回最终是否拿到凭据。

    **阻塞**（最长 DESKTOP_LOGIN_TIMEOUT 秒），调用方必须放到后台线程里跑。
    凭据本来就有 → 立即返回 True，不开窗口。
    """
    spec = _DESKTOP_LOGIN_SPEC.get(key)
    if not spec:
        return True
    label = spec["label"]
    ok, why = desktop_cred_probe(key, station)
    if ok:
        log(f"[登录] {label} 凭据已就绪（{why}），无需打开桌面端")
        return True
    with _desktop_login_lock:
        if key in _desktop_login_busy:
            log(f"[登录] {label} 已在等待登录中，跳过重复拉起桌面端")
            return False
        _desktop_login_busy.add(key)
    before: set = set()
    image = ""
    try:
        exe = find_install(spec["install_kind"], station if spec["station"] else None)
        if not exe or not os.path.isfile(exe):
            log(f"[登录] ✗ 未找到 {label} 桌面端（{spec['hint']}）"
                f" —— 请手动打开并登录一次，或在「程序位置」里指定")
            return False
        image = os.path.basename(exe)
        before = _pids_by_image(image)
        if key == "ca":                      # 记录凭证库基线，用于检测"刚登录"
            try:
                _CA_STORE_BASELINE["fp"] = import_codearts(lambda *a: None).store_fingerprint()
            except Exception:                # noqa: BLE001
                _CA_STORE_BASELINE.pop("fp", None)
        log(f"[登录] 未检测到 {label} 凭据（{why}），正在打开桌面端：{exe}")
        try:
            subprocess.Popen([exe], cwd=os.path.dirname(exe))
        except Exception as e:  # noqa: BLE001
            log(f"[登录] ✗ 启动 {label} 桌面端失败：{type(e).__name__}: {e}")
            return False
        log(f"[登录] 请在 {label} 桌面端完成登录；拿到凭据后会**自动关闭**它"
            f"（最长等待 {int(DESKTOP_LOGIN_TIMEOUT)} 秒）")
        t0 = time.time()
        ok2 = False
        nxt_tip = 30.0
        while time.time() - t0 < DESKTOP_LOGIN_TIMEOUT:
            time.sleep(DESKTOP_LOGIN_POLL)
            ok2, why = desktop_cred_probe(key, station)
            if ok2:
                break
            el = time.time() - t0
            if el >= nxt_tip:
                log(f"[登录] 仍在等待 {label} 登录…（{int(el)}s/{int(DESKTOP_LOGIN_TIMEOUT)}s）")
                nxt_tip += 30.0
            # 桌面端自己全退了也有可能是登录完成（部分版本登录后自退）
            if not (_pids_by_image(image) - before):
                ok2, why = desktop_cred_probe(key, station)
                if not ok2:
                    log(f"[登录] {label} 桌面端已退出但凭据仍未就绪，停止等待")
                break
        if ok2:
            log(f"[登录] ✓ 已拿到 {label} 凭据（{why}）")
        else:
            log(f"[登录] ✗ 等待 {label} 登录未完成（超时或窗口被关闭）")
        return ok2
    finally:
        _desktop_login_busy.discard(key)
        if key == "ca":
            _CA_STORE_BASELINE.pop("fp", None)
        if image:
            # 只关「自己拉起来的」—— 登录前就开着的桌面端不动
            _kill_pids(_pids_by_image(image) - before, label, log)


# ---------------------------------------------------------------------------
# 服务包装（uvicorn 线程）
# ---------------------------------------------------------------------------

class ProxyService:
    def __init__(self, key: str, title: str):
        self.key = key
        self.title = title
        self.server = None
        self.thread = None
        self.error: str | None = None
        self.started_at: float | None = None

    @property
    def running(self) -> bool:
        return (self.server is not None and self.thread is not None
                and self.thread.is_alive() and not self.server.should_exit)

    def start(self, app_obj, host: str, port: int):
        import uvicorn
        cfg = uvicorn.Config(app_obj, host=host, port=port, log_level="info", lifespan="on")
        self.server = uvicorn.Server(cfg)
        self.error = None
        self.started_at = time.time()
        self.thread = threading.Thread(target=self._serve, name=f"{self.key}-uvicorn", daemon=True)
        self.thread.start()

    def _serve(self):
        try:
            self.server.run()
        except Exception as e:  # noqa: BLE001
            self.error = f"{type(e).__name__}: {e}"

    def stop(self, timeout=10.0):
        if self.server is not None:
            self.server.should_exit = True
        if self.thread is not None:
            self.thread.join(timeout)
        self.server = None
        self.thread = None
        self.started_at = None


