def mc_model_caps() -> dict:
    """{模型名: {"type","images","ctx","max_out"}} —— 取自桌面端 ohmyagent/settings.json。

    与 monkeycode2openai 同源，用于在界面上标注模型能力：
      · images   ← supports_images（是否支持图片输入）
      · type     ← 协议（anthropic / openai-responses，两者都已支持，仅作参考）
    键同时含全名与去掉 `monkeycode-basic/` 前缀的短名，方便按候选名直接匹配。

    注意：上游**没有**逐模型的工具调用能力字段（只有 type/thinking/
    supports_images/context_window/max_output），所以工具调用无从按模型标注。
    """
    app = "com.chaitin.baizhi.monkeycode"
    home = Path.home()
    for base in (
        os.environ.get("APPDATA"),
        home / "AppData" / "Roaming",
        os.environ.get("LOCALAPPDATA"),
        home / "AppData" / "Local",
    ):
        if not base:
            continue
        p = Path(base) / app / "ohmyagent" / "settings.json"
        if not p.is_file():
            continue
        try:
            d = json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            return {}
        out: dict = {}
        pfx = "monkeycode-basic/"
        for v in (d.get("models") or {}).values():
            if not isinstance(v, dict):
                continue
            if "proxy.monkeycode-ai" not in str(v.get("base_url") or ""):
                continue
            name = v.get("model")
            if not name:
                continue
            caps = {"type": v.get("type"),
                    "images": v.get("supports_images"),
                    "ctx": v.get("context_window"),
                    "max_out": v.get("max_output")}
            out[str(name)] = caps
            if str(name).startswith(pfx):
                out[str(name)[len(pfx):]] = caps
        return out
    return {}


def monkeycode_upstream_base() -> str:
    """探测 MonkeyCode 当前上游 base_url（仅用于界面显示）。

    优先官方代理凭据 monkeycode-ohmyagent-key.json（与 monkeycode2openai 的
    auto_configure 一致，那里会走签名通道）；否则取 config.json 里 base_url
    含 /openai 的条目——本网关只转发 OpenAI 协议，而 config.json 同时存在
    /api/anthropic 与 /api/openai/v1，取错会 404（上游回 "Gateway 路由不存在"）。
    无 OpenAI 端点时才回退第一条带 key 的条目。
    """
    app = "com.chaitin.baizhi.monkeycode"
    home = Path.home()
    roots = (
        os.environ.get("APPDATA"),
        home / "AppData" / "Roaming",
        os.environ.get("LOCALAPPDATA"),
        home / "AppData" / "Local",
    )
    for base in roots:
        if not base:
            continue
        p = Path(base) / app / "monkeycode-ohmyagent-key.json"
        if p.is_file():
            try:
                d = json.loads(p.read_text(encoding="utf-8"))
            except Exception:
                continue
            if d.get("base_url") and d.get("signing_secret"):
                # 后缀文案与其它通道统一：中文括号、不带 "·"（避免和外层 " · " 分隔符打架）
                return d["base_url"].rstrip("/") + "（官方代理）"
    for base in roots:
        if not base:
            continue
        p = Path(base) / app / "config.json"
        if p.is_file():
            try:
                data = json.loads(p.read_text(encoding="utf-8"))
            except Exception:
                continue
            keyed = [m["base_url"].rstrip("/") for m in (data.get("models") or [])
                     if m.get("api_key") and m.get("base_url")]
            if not keyed:
                return ""
            for u in keyed:
                if "/openai" in u.lower():
                    return u
            return keyed[0]
    return ""


