    cb_station = tk.StringVar(value=settings.get("cb_station", "auto") or "auto")

    def _cb_station_changed():
        """切换「版本」→ 立刻换掉正在用的凭据（不必重启服务）。

        凭据只是 CONFIG["cred"] 这个对象，换掉即时生效；日志里打出切过去之后
        真正在用的账号与后端，避免"选了国内却仍走国际"这种看不出来的情况。
        """
        _persist()
        _st = None if cb_station.get() == "auto" else cb_station.get()
        emit(f"[cb] 版本 → {cb_station.get()}")
        try:
            conv = sys.modules.get("codebuddy2openai")
            if conv is not None and hasattr(conv, "apply_station"):
                s = conv.apply_station(_st)
                emit(f"[cb] 已切换 · 账号={s.get('nickname')} · {s.get('domain')}"
                     f" → {s.get('backend')}（{s.get('auth_file')}）")
            else:
                emit("[cb] 服务未启动，下次启动时生效")
        except Exception as e:  # noqa: BLE001
            emit(f"[cb] 切换失败：{type(e).__name__}: {e}")
