    qd_station = tk.StringVar(value=settings.get("qd_station", "auto") or "auto")

    def _qd_station_changed():
        """切换「版本」→ 立刻把该站点的 CLI 路径与 PAT 推给运行中的服务。"""
        _persist()
        _choice = qd_station.get()
        emit(f"[qd] 版本 → {_choice}")
        try:
            qd = sys.modules.get("qoder2openai")
            if qd is None:
                emit("[qd] 服务未启动，下次启动时生效")
            else:
                _st = qd.resolve_station(
                    _choice, qd_pat_cn.get().strip(), qd_pat_intl.get().strip())
                _cli = (qd_path_cn if _st == "cn" else qd_path_intl).get().strip()
                _pat = (qd_pat_cn if _st == "cn" else qd_pat_intl).get().strip()
                qd.apply_station(_st, cli_path=_cli, pat=_pat)
                emit(f"[qd] 已热切换到 {qd.station_meta()['label']}"
                     f"（CLI：{_cli or '自动探测'}）")
        except Exception as e:  # noqa: BLE001
            emit(f"[qd] 切换失败：{type(e).__name__}: {e}")
        ui(refresh_qd_info)
        ui(lambda: refresh_creds(True))

