    def _refresh_urls():
        try:
            p = int(cb_port.get()) if cb_port.get().strip().isdigit() else 8787
        except ValueError:
            p = 8787
        host = "127.0.0.1"  # URL 提示固定回环，即便监听 0.0.0.0 也可用
        cb_url.set(f"http://{host}:{p}/v1")
        try:
            p3 = int(mc_port.get()) if mc_port.get().strip().isdigit() else 9000
        except ValueError:
            p3 = 9000
        mc_url.set(f"http://{host}:{p3}/v1")
        try:
            p4 = int(ca_port.get()) if ca_port.get().strip().isdigit() else 9100
        except ValueError:
            p4 = 9100
        ca_url.set(f"http://{host}:{p4}/v1")
        try:
            p5 = int(lo_port.get()) if lo_port.get().strip().isdigit() else 9400
        except ValueError:
            p5 = 9400
        lo_url.set(f"http://{host}:{p5}/v1")
        try:
            p6 = int(qd_port.get()) if qd_port.get().strip().isdigit() else 9500
        except ValueError:
            p6 = 9500
        qd_url.set(f"http://{host}:{p6}/v1")

