    def set_install_path(key: str, path: str, station: str | None = None):
        def _apply():
            if key == "cb" and station in ("cn", "intl"):
                e = cb_path_cn if station == "cn" else cb_path_intl
            elif key == "qd" and station in ("cn", "intl"):
                e = qd_path_cn if station == "cn" else qd_path_intl
            else:
                e = {"cb": cb_path_cn, "mc": mc_path, "rc": rc_path,
                     "lo": lo_path, "qd": qd_path_intl}.get(key, ca_path)
            e.delete(0, "end")
            e.insert(0, path)
        ui(_apply)

    def browse_install(key: str, station: str | None = None):
        """点「浏览…」只弹一个文件选择框。

        以前是「文件框 → 取消 → 文件夹框」两步兜底（因为 tkinter 的对话框没
        法同时选文件和文件夹）。但取消本意就是放弃，再弹一个默认落在「文档」
        的文件夹框，会让人以为点错了。现在取消即返回。
        要指定文件夹，把文件夹路径直接粘进「程序位置」输入框即可 ——
        resolve_install_input 会自动在其中定位主程序 exe。

        station：WorkBuddy 用 —— "cn"/"intl" 决定写入哪个路径框（国内/国际两版
        同时装、各占一行，互不覆盖）。
        """
        from tkinter import filedialog
        if key == "qd":
            # Qoder 的「程序位置」= IDE 主程序 exe（和其它通道一致）；
            # CLI 引擎与登录态都从这个安装目录里自动取。
            p = filedialog.askopenfilename(
                    title="选择 Qoder 主程序（Qoder.exe / Qoder CN.exe）",
                    filetypes=[("可执行文件", "*.exe"), ("所有文件", "*.*")])
            if not p:
                return
            settings["qd_path_cn" if station == "cn" else "qd_path_intl"] = p
            save_settings(settings)
            set_install_path("qd", p, station)
            emit(f"[qd/{station}] 程序位置已设置: {p}"
                 + ("" if Path(p).exists() else "  ⚠ 路径不存在"))
            return
        p = filedialog.askopenfilename(
                title="选择主程序 exe（也可把文件夹路径粘到「程序位置」框）",
                filetypes=[("可执行文件", "*.exe"), ("所有文件", "*.*")])
        if not p:
                return
        kind = {"cb": "wb", "mc": "mc", "rc": "rc", "lo": "lo"}.get(key, "ca")
        resolved = resolve_install_input(p, kind)
        if key == "cb" and station in ("cn", "intl"):
            skey = "wb_path_cn" if station == "cn" else "wb_path_intl"
            settings[skey] = resolved
            tag = f"cb/{station}"
        else:
            settings[{"cb": "wb_path", "mc": "mc_path", "rc": "rc_path",
                      "lo": "lo_path"}.get(key, "ca_path")] = resolved
            tag = key
        save_settings(settings)
        set_install_path(key, resolved, station)
        warn = "" if Path(resolved).exists() else "  ⚠ 路径不存在"
        emit(f"[{tag}] 程序位置已设置: {resolved}{warn}")

    def launch_program(key: str, station: str | None = None):
        """启动程序位置框里的桌面端程序（WorkBuddy 按站点取对应那一行）"""
        if key == "cb" and station in ("cn", "intl"):
            entry = cb_path_cn if station == "cn" else cb_path_intl
        elif key == "qd" and station in ("cn", "intl"):
            entry = qd_path_cn if station == "cn" else qd_path_intl
        else:
            entry = {"cb": cb_path_cn, "mc": mc_path, "rc": rc_path,
                     "lo": lo_path, "qd": qd_path_intl}.get(key, ca_path)
        p = entry.get().strip()
        tag = f"{key}/{station}" if (key in ("cb", "qd") and station) else key
        if not p:
            emit(f"[{tag}] 程序位置为空，先点“浏览…”指定或等自动探测")
            return
        if not Path(p).exists():
            emit(f"[{tag}] 路径不存在，无法启动: {p}")
            return
        try:
            os.startfile(p)  # noqa: S606
            emit(f"[{tag}] 已启动: {p}")
        except Exception as e:  # noqa: BLE001
            emit(f"[{tag}] 启动失败：{e}")

    # ---------------- 系统托盘 ----------------
    tray_icon = None

    def make_tray_image():
        try:
            from PIL import Image, ImageDraw
            img = Image.new("RGBA", (64, 64), (0, 0, 0, 0))
            d = ImageDraw.Draw(img)
            d.rounded_rectangle([4, 4, 60, 60], radius=14, fill=(24, 27, 32, 255))
            d.ellipse([12, 18, 30, 36], fill=(34, 197, 94, 255))    # 绿点：OpenAI 通道
            return img
        except Exception:
            return None

    def show_from_tray():
        """从系统托盘恢复主窗口（deiconify + 置前）。
        注意：这个 def 行曾经丢失，函数体被留在 make_tray_image() 的 return 之后成了死代码，
        菜单点击会 NameError: name 'show_from_tray' is not defined。"""
        try:
            root.deiconify()
            root.lift()
            try:
                root.focus_force()
            except Exception:
                pass
        except Exception:  # noqa: BLE001
            pass

    def create_tray():
        nonlocal tray_icon
        if tray_icon is not None:
            return
        try:
            import pystray
            img = make_tray_image()
            if img is None:
                emit("[tray] 无法生成托盘图标，关闭窗口将直接退出")
                return
            menu = pystray.Menu(
                pystray.MenuItem("显示主窗口", lambda *a: ui(show_from_tray), default=True),
                pystray.MenuItem("▶ 一键启动", lambda *a: ui(lambda: threading.Thread(target=start_all, daemon=True).start())),
                pystray.MenuItem("■ 全部停止", lambda *a: ui(lambda: threading.Thread(target=stop_all, daemon=True).start())),
                pystray.Menu.SEPARATOR,
                pystray.MenuItem("退出", lambda *a: ui(real_exit)),
            )
            tray_icon = pystray.Icon(APP_NAME, img, f"{APP_NAME} · WorkBuddy/MonkeyCode 反代网关", menu)
            threading.Thread(target=tray_icon.run, daemon=True).start()
            emit("[tray] 系统托盘已启用：点 × 缩小到托盘，服务继续运行")
        except Exception as e:  # noqa: BLE001
            tray_icon = None
            emit(f"[tray] 系统托盘不可用（{e}），关闭窗口将直接退出")

