    def _host() -> str:
        return "0.0.0.0" if lan_var.get() else "127.0.0.1"

    # ---------------- Hermes Agent 集成 ----------------
    def hermes_profile_homes() -> list:
        """本机全部 Hermes profile 目录（默认 + profiles/*，以存在 config.yaml 为准）"""
        homes = []
        cands = [Path.home() / ".hermes",
                 _localappdata() / "hermes"]
        profdir = _localappdata() / "hermes" / "profiles"
        try:
            for sub in sorted(profdir.iterdir()):
                if sub.is_dir():
                    cands.append(sub)
        except OSError:
            pass
        seen = set()
        for h in cands:
            try:
                key = str(h.resolve())
            except OSError:
                key = str(h)
            if key in seen:
                continue
            seen.add(key)
            if (h / "config.yaml").is_file():
                homes.append(h)
        return homes

    def hermes_config_path() -> Path:
        # 活动 profile 优先（桌面端/HERMES_HOME），回退默认 ~/.hermes
        home = os.environ.get("HERMES_HOME", "").strip()
        if home:
            return Path(home) / "config.yaml"
        return Path.home() / ".hermes" / "config.yaml"

    def hermes_env_path(home=None) -> Path:
        base = Path(home) if home else hermes_config_path().parent
        return base / ".env"

    def read_hermes_config(path=None) -> dict | None:
        p = Path(path) if path else hermes_config_path()
        if not p.is_file():
            return None
        try:
            import yaml
            return yaml.safe_load(p.read_text(encoding="utf-8")) or {}
        except Exception as e:
            emit(f"[hermes] 读取配置失败({p}): {e}")
            return None

    def write_hermes_config(cfg: dict, path=None) -> bool:
        p = Path(path) if path else hermes_config_path()
        try:
            import yaml
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(yaml.safe_dump(cfg, allow_unicode=True, sort_keys=False), encoding="utf-8")
            return True
        except Exception as e:
            emit(f"[hermes] 写入配置失败({p}): {e}")
            return False

    def _buddyz_key_env(pid: str) -> str:
        # 与 hermes 官方 custom_endpoint_key_env 同规则
        slug = re.sub(r"[^A-Z0-9]+", "_", pid.upper()).strip("_")
        return f"HERMES_CUSTOM_{slug}_API_KEY" if slug else "HERMES_CUSTOM_API_KEY"

    def _ensure_hermes_env_key(var: str, val: str, home=None):
        """key 写入 profile .env（无查重追加）；对应 hermes 的 key_env 机制"""
        p = hermes_env_path(home)
        try:
            cur = p.read_text(encoding="utf-8") if p.is_file() else ""
            if re.search(rf"(?m)^{re.escape(var)}\s*=", cur):
                return
            if cur and not cur.endswith("\n"):
                cur += "\n"
            cur += f"{var}={val}\n"
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(cur, encoding="utf-8")
        except OSError as e:  # noqa: BLE001
            emit(f"[hermes] 写入 .env 失败: {e}")

    def _buddyz_hermes_entries(host: str, cb_p: int, mc_p: int, ca_p: int, rc_p: int,
                               lo_p: int, qd_p: int = 9500) -> dict:
        """GUI 侧包装：用**界面当前**的端口与模型选择，套模块级 hermes_entries。

        schema 只在 hermes_entries 里定义一份，避免 GUI / 无界面两条路各写一套漂移。
        """
        _ports = {"cb": cb_p, "mc": mc_p, "ca": ca_p,
                  "rc": rc_p, "lo": lo_p, "qd": qd_p}
        _s = dict(settings)
        for _k, _p in _ports.items():
            _s[f"{_k}_port"] = _p
            _s[f"{_k}_models"] = eff_models(_k)     # 跟随界面里"当前生效"的模型
        return hermes_entries(_s, host)

    def sync_to_hermes():
        homes = hermes_profile_homes()
        if not homes:
            emit("[hermes] 未找到任何 Hermes profile 配置，请确认 Hermes Agent 已安装")
            return
        host = _host()
        cb_p = int(cb_port.get()) if cb_port.get().strip().isdigit() else 8787
        mc_p = int(mc_port.get()) if mc_port.get().strip().isdigit() else 9000
        ca_p = int(ca_port.get()) if ca_port.get().strip().isdigit() else 9100
        rc_p = int(rc_port.get()) if rc_port.get().strip().isdigit() else 9200
        lo_p = int(lo_port.get()) if lo_port.get().strip().isdigit() else 9400
        qd_p = int(qd_port.get()) if qd_port.get().strip().isdigit() else 9500

        # 只同步勾选的 provider
        all_entries = _buddyz_hermes_entries(host, cb_p, mc_p, ca_p, rc_p, lo_p, qd_p)
        selected = {}
        names = []
        if hr_sync_cb.get():
            selected["buddyz-cb"] = all_entries["buddyz-cb"]
            names.append("WorkBuddy")
        if hr_sync_mc.get():
            selected["buddyz-mc"] = all_entries["buddyz-mc"]
            names.append("MonkeyCode")
        if hr_sync_ca.get():
            selected["buddyz-ca"] = all_entries["buddyz-ca"]
            names.append("华为云")
        if hr_sync_rc.get():
            selected["buddyz-rc"] = all_entries["buddyz-rc"]
            names.append("小浣熊")
        if hr_sync_lo.get():
            selected["buddyz-lo"] = all_entries["buddyz-lo"]
            names.append("Loomy")
        if hr_sync_qd.get():
            selected["buddyz-qd"] = all_entries["buddyz-qd"]
            names.append("Qoder")
        if not selected:
            emit("[hermes] 未勾选任何反代，请先勾选要同步的服务")
            return

        ok_homes = []
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            # 先移除所有 buddyz-*，再写入选中的
            for k in [k for k in providers if str(k).startswith("buddyz-")]:
                providers.pop(k, None)
            providers.update(selected)
            cfg["providers"] = providers
            # 占位 key 进各 profile .env（本地反代不校验，hermes 侧要求 key 存在）
            for pid in selected:
                _ensure_hermes_env_key(_buddyz_key_env(pid), "local-noauth", home)
            if write_hermes_config(cfg, home / "config.yaml"):
                ok_homes.append(home.name)
        if ok_homes:
            emit(f"[hermes] 已同步 {len(selected)} 个 provider（{' / '.join(names)}）到 {len(ok_homes)} 个 profile：{', '.join(ok_homes)}")
            hermes_status_label.config(foreground="#28a745")
            hermes_status_var.set(f"已同步（{' / '.join(names)}）×{len(ok_homes)}配置")
            _persist()
        else:
            emit("[hermes] 同步失败")

    def remove_from_hermes():
        homes = hermes_profile_homes()
        if not homes:
            emit("[hermes] 未找到任何 Hermes profile 配置")
            return
        total = 0
        touched = []
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            buddyz_keys = [k for k in providers if str(k).startswith("buddyz-")]
            if not buddyz_keys:
                continue
            for k in buddyz_keys:
                providers.pop(k, None)
            cfg["providers"] = providers
            if write_hermes_config(cfg, home / "config.yaml"):
                total += len(buddyz_keys)
                touched.append(home.name)
        if total == 0:
            emit("[hermes] 所有 profile 中均未找到 BuddyZGateway 的 provider")
            hermes_status_var.set("未同步")
            hermes_status_label.config(foreground="#888")
        else:
            emit(f"[hermes] 已从 {len(touched)} 个 profile 移除 {total} 个 provider（.env 占位 key 保留）：{', '.join(touched)}")
            hermes_status_label.config(foreground="#888")
            hermes_status_var.set("未同步")

    def refresh_hermes_status():
        homes = hermes_profile_homes()
        if not homes:
            hermes_status_var.set("未检测到 Hermes")
            hermes_status_label.config(foreground="#888")
            return
        buddyz_names = []
        name_map = {"buddyz-cb": "WorkBuddy", "buddyz-mc": "MonkeyCode",
                    "buddyz-ca": "华为云", "buddyz-rc": "小浣熊",
                    "buddyz-lo": "Loomy", "buddyz-qd": "Qoder"}
        hit_homes = 0
        for home in homes:
            cfg = read_hermes_config(home / "config.yaml")
            if cfg is None:
                continue
            providers = cfg.get("providers")
            if not isinstance(providers, dict):
                providers = {}
            found_here = False
            for k in providers:
                if str(k) in name_map:
                    if name_map[str(k)] not in buddyz_names:
                        buddyz_names.append(name_map[str(k)])
                    found_here = True
            if found_here:
                hit_homes += 1
        if buddyz_names:
            hermes_status_var.set(f"已同步（{' / '.join(buddyz_names)}）×{hit_homes}/{len(homes)}配置")
            hermes_status_label.config(foreground="#28a745")
        else:
            hermes_status_var.set("未同步")
            hermes_status_label.config(foreground="#888")

    def eff_models(key: str) -> list:
        """当前生效的暴露模型列表。空存储时 cb/ca/mc 返回内置默认；
        rc 返回 [] = 上游 catalog 全量（以小浣熊线上为准）。"""
        stored = settings.get(f"{key}_models") or []
        if stored:
            return list(stored)
        if key == "cb":
            return list(CB_MODEL_CANDIDATES)
        if key == "ca":
            return list(CA_MODEL_CANDIDATES)
        if key == "rc":
            return []
        if key == "lo":
            return list(stored) or list(LO_DEFAULT_MODELS)
        if key == "qd":
            # 模型名两版不同 → 跟随当前生效站点
            mod = sys.modules.get("qoder2openai")
            if mod is not None:
                try:
                    st = mod.resolve_station(
                        qd_station.get(), qd_pat_cn.get().strip(),
                        qd_pat_intl.get().strip())
                    return list(mod.STATIONS[st]["models"])
                except Exception:  # noqa: BLE001
                    pass
            return list(QD_DEFAULT_MODELS)
        return list(MC_DEFAULT_MODELS)

    def apply_models_live(key: str, sel: list):
        """把模型选择立即应用到已加载的核心（无需重启服务）。"""
        if key == "cb":
            conv = sys.modules.get("converter")
            if conv is not None:
                conv.CONFIG["exposed_models"] = list(sel)
        elif key == "mc":
            mc = sys.modules.get("monkeycode2openai")
            if mc is not None:
                mc.CONFIG["exposed_models"] = list(sel)
        elif key == "ca":
            ca = sys.modules.get("codearts2openai")
            if ca is not None:
                ca.CONFIG["exposed_models"] = list(sel)
        elif key == "rc":
            rc = sys.modules.get("raccoon2openai")
            if rc is not None:
                rc.CONFIG["exposed_models"] = list(sel)
        elif key == "lo":
            lo = sys.modules.get("loomy2openai")
            if lo is not None:
                lo.CONFIG["exposed_models"] = list(sel)

